-- SMU+ seed data. Generated by mustangs-plus-tools/build_seed.js from assets/data.js and assets/content.js.
-- Run AFTER schema.sql. Safe to re-run: it upserts reference rows and replaces the sample threads (ids 1-999).
-- Every board user and post here is FICTIONAL sample content for a class concept.
begin;
on conflict (id) do update set name=excluded.name,description=excluded.description,premium=excluded.premium,grp=excluded.grp,sort=excluded.sort;
on conflict (handle) do update set display_name=excluded.display_name,tier_label=excluded.tier_label,since=excluded.since,post_count=excluded.post_count,staff=excluded.staff;
alter table public.posts disable trigger posts_after_insert;
delete from public.threads where id < 1000 and author_handle is not null;
alter table public.posts enable trigger posts_after_insert;
select setval(pg_get_serial_sequence('public.threads','id'), greatest(1000,(select max(id) from public.threads)));
select setval(pg_get_serial_sequence('public.posts','id'), greatest(100000,(select max(id) from public.posts)));
on conflict (id) do update set type=excluded.type,category=excluded.category,label=excluded.label,title=excluded.title,description=excluded.description,duration=excluded.duration,members_only=excluded.members_only,sport=excluded.sport,sort=excluded.sort;
commit;
